[
  {"ref":"SH-4420","vessel":"MV-VEGA","status":"Delayed","delay_h":9,"score":35,"band":"nominal","drivers":["Delayed status","9h delay"]},
  {"ref":"SH-4417","vessel":"MV-ATLAS","status":"Delayed","delay_h":6,"score":32,"band":"nominal","drivers":["Delayed status","6h delay"]}
]

