  {"ref":"SH-4420","vessel":"MV-VEGA","score":35,"band":"nominal","drivers":["Delayed status","9h delay"]},
  {"ref":"SH-4417","vessel":"MV-ATLAS","score":32,"band":"nominal","drivers":["Delayed status","6h delay"]},
  {"ref":"SH-4419","vessel":"MV-ORION","score":17,"band":"nominal","drivers":["At Risk status","2h delay"]}
]

Recovery options (JSON):
[
  {
    "ref": "SH-4420",
    "vessel": "MV-VEGA",
